using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
namespace Ara {
 public static class NotificationBufferTests {
  static void Assert(bool value,string reason){if(!value)throw new Exception(reason);}
  static State New(){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,d);return s;}
  static CellBlock Meal(GridPlan p,string id){return p.Blocks.Single(x=>x.MealId==id);}
  static void First(State s,int delay,int count=3){var d=s.Days[0];d.Records.Add(new CellBlock{Id="eaten-first",Start=d.Wake.AddMinutes(30+delay),Count=count,MealId="b1",Category="식사",Score=2});}
  public static void Run(Action<string,Action> check,string dir){
   check("zone phases: front thirty precedes post-shower twenty, facts and target preserved",()=>{var s=New();First(s,50);var d=s.Days[0];var p=GridEngine.Build(s,d);var first=d.Records[0];Assert(p.Blocks.Single(x=>x.Category=="존2").Start==first.Start.AddMinutes(90),"front minimum reached");Assert(Meal(p,"b6").Start==first.Start.AddMinutes(190),"post cut20");Assert(p.Changes.FindIndex(x=>x.Contains("1끼니→존2 대기"))<p.Changes.FindIndex(x=>x.Contains("존2·샤워→2끼니")),"front first");Assert(p.Saved==50&&p.Overflow==0&&first.Count==3&&first.Score==2,"facts");});
   check("zone phases: sixty minutes uses front and shower waits without removing third",()=>{var s=New();First(s,60);var p=GridEngine.Build(s,s.Days[0]);Assert(Meal(p,"b6").Start==s.Days[0].Records[0].Start.AddHours(3),"meal floor");Assert(Meal(p,"b10")!=null&&p.Blocks.Single(x=>x.Category=="존2").Count==4&&p.Overflow==0,"retain third and zone");});
   check("zone phases: long actual eating respects end plus sixty minutes",()=>{var s=New();First(s,60,9);var p=GridEngine.Build(s,s.Days[0]);var first=s.Days[0].Records[0];var zone=p.Blocks.FirstOrDefault(x=>x.Category=="존2");Assert(zone!=null&&zone.Start>=first.End.AddHours(1),"actual end floor");Assert(Meal(p,"b6").Start>=first.Start.AddHours(3),"meal floor");});
   check("zone phases: score-fragmented first meal has one continuous eating end",()=>{var s=New();First(s,30,3);var d=s.Days[0];d.Records.Add(new CellBlock{Id="tail",Start=d.Records[0].End,Count=3,Category="식사",Score=5});var p=GridEngine.Build(s,d);Assert(Adaptive.MealEnd(d,p,"b1")==d.Records[1].End,"fragment end");var zone=p.Blocks.FirstOrDefault(x=>x.Category=="존2");Assert(zone==null||zone.Start>=d.Records[1].End.AddHours(1),"post meal rest");Assert(GridEngine.Total(d)==21,"score facts");});
   check("zone phases: delay sweep retains three-hour meal gaps and 150-minute second-to-weight gap",()=>{for(int delay=0;delay<=600;delay+=10){var s=New();First(s,delay);var p=GridEngine.Build(s,s.Days[0]);var meals=p.Blocks.Where(x=>!string.IsNullOrEmpty(x.MealId)).OrderBy(x=>x.Start).ToList();for(int i=1;i<meals.Count;i++)Assert(meals[i].Start>=meals[i-1].Start.AddHours(3),"meal gap "+delay);Assert(p.Blocks.Single(x=>x.Category=="웨이트").Start>=Meal(p,"b6").Start.AddMinutes(150),"weight gap");}});
   check("notification feed: meal prep, exercise, dim and sleep timing",()=>{var s=New();var d=s.Days[0];var p=GridEngine.Build(s,d);var feed=ScheduleNotifications.Feed(s,d.Wake);var first=feed.items.Single(x=>x.title=="1끼니 준비");Assert(first.at==ScheduleNotifications.Epoch(Meal(p,"b1").Start.AddMinutes(-5)),"prep five before");Assert(feed.items.Any(x=>x.title=="존2")&&feed.items.Any(x=>x.title=="웨이트"),"exercise");var sleep=Adaptive.EstimatedSleep(s,d,p);Assert(feed.items.Single(x=>x.title=="소등 시간").at==ScheduleNotifications.Epoch(sleep.AddHours(-2)),"dim");Assert(feed.items.Single(x=>x.title=="수면 예상 시간").at==ScheduleNotifications.Epoch(sleep),"sleep");});
   check("notification feed: actual meal cancels its reminder and reflects future changes without mutating data",()=>{var s=New();var before=ScheduleNotifications.Feed(s,s.Days[0].Wake);First(s,60);string facts=System.Text.Encoding.UTF8.GetString(PhoneCodec.Json(s));var after=ScheduleNotifications.Feed(s,s.Days[0].Wake);Assert(!after.items.Any(x=>x.title=="1끼니 준비"),"eaten excluded");Assert(after.items.Any(x=>x.title=="2끼니 준비"),"future retained");Assert(facts==System.Text.Encoding.UTF8.GetString(PhoneCodec.Json(s)),"read only feed");});
   check("notification feed: expired entries excluded and phone independent of PC checkbox",()=>{var s=New();s.Notifications=false;var now=s.Days[0].Wake;var feed=ScheduleNotifications.Feed(s,now);Assert(feed.items.Count>0,"phone independent");long instant=ScheduleNotifications.Epoch(now.AddDays(2));Assert(ScheduleNotifications.Feed(s,now.AddDays(2)).items.All(x=>x.expires>instant),"no stale notifications");});
   check("notification feed: Android delayed delivery survives thirty minutes but not two hours",()=>{var s=New();var d=s.Days[0];var first=ScheduleNotifications.Feed(s,d.Wake).items.Single(x=>x.title=="1끼니 준비");var at=d.Wake.AddMinutes(20);Assert(ScheduleNotifications.Feed(s,at.AddMinutes(30)).items.Any(x=>x.key==first.key),"not silently expired at thirty minutes");Assert(!ScheduleNotifications.Feed(s,at.AddHours(2)).items.Any(x=>x.key==first.key),"bounded stale window");});
   check("notification feed: late grace never revives a performed meal",()=>{var s=New();var d=s.Days[0];var first=ScheduleNotifications.Feed(s,d.Wake).items.Single(x=>x.title=="1끼니 준비");First(s,0);Assert(!ScheduleNotifications.Feed(s,d.Wake.AddHours(1)).items.Any(x=>x.key==first.key),"completed meal stays cancelled");});
   check("notification status: Windows UTF8 BOM is readable and failure is not success",()=>{string path=Path.Combine(dir,"notification-data.json");File.WriteAllText(WindowsNotifications.StatusPath(path),"{\"state\":\"submitted\",\"setting\":\"Enabled\",\"history\":1}",new System.Text.UTF8Encoding(true));Assert(WindowsNotifications.Last(path).Success&&WindowsNotifications.Last(path).history==1,"BOM");Assert(!new ToastResult{state="blocked"}.Success,"blocked retry");});
  }
 }
}
